module palindrome_search (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] char_0, char_1, char_2, char_3, char_4, char_5, char_6, char_7,\n    input [7:0] char_8, char_9, char_10, char_11, char_12, char_13, char_14, char_15,\n    input [7:0] char_16, char_17, char_18, char_19, char_20, char_21, char_22, char_23,\n    input [7:0] char_24, char_25, char_26, char_27, char_28, char_29, char_30, char_31,\n    input [7:0] char_32, char_33, char_34, char_35, char_36, char_37, char_38, char_39,\n    input [7:0] char_40, char_41, char_42, char_43, char_44, char_45, char_46, char_47,\n    input [7:0] char_48, char_49,\n    input [5:0] length,\n    output reg [5:0] result_start,\n    output reg [5:0] result_len,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE     = 3'd0;\n    localparam [2:0] LOAD     = 3'd1;\n    localparam [2:0] SEARCH   = 3'd2;\n    localparam [2:0] COMPARE  = 3'd3;\n    localparam [2:0] UPDATE   = 3'd4;\n    localparam [2:0] FINISH   = 3'd5;\n\n    // Internal registers\n    reg [2:0] state;\n    reg [5:0] i_reg, j_reg, k_reg;\n    reg [5:0] curr_start, curr_len;\n    reg [5:0] best_start_reg, best_len_reg;\n    reg [7:0] str_reg [0:49];\n    reg [5:0] len_reg;\n    reg loop_flag;\n    reg valid_palindrome_reg;\n\n    // Check valid character function\n    function is_valid_char;\n        input [7:0] char;\n        begin\n            is_valid_char = (char == 8'h61) || (char == 8'h62);  // 'a' or 'b'\n        end\n    endfunction\n\n    // Palindrome checker\n    function check_palindrome;\n        input [5:0] left_idx;\n        input [5:0] right_idx;\n        integer left_idx_int;\n        integer right_idx_int;\n        begin\n            left_idx_int = left_idx;\n            right_idx_int = right_idx;\n            check_palindrome = 1'b1;\n            while (left_idx_int < right_idx_int) begin\n                if (!is_valid_char(str_reg[left_idx_int]) || \n                    !is_valid_char(str_reg[right_idx_int]) || \n                    str_reg[left_idx_int] != str_reg[right_idx_int]) begin\n                    check_palindrome = 1'b0;\n                end\n                left_idx_int = left_idx_int + 1;\n                right_idx_int = right_idx_int - 1;\n            end\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            done <= 1'b0;\n            result_start <= 6'd0;\n            result_len <= 6'd0;\n            i_reg <= 6'd0;\n            j_reg <= 6'd0;\n            k_reg <= 6'd0;\n            best_start_reg <= 6'd0;\n            best_len_reg <= 6'd0;\n            curr_start <= 6'd0;\n            curr_len <= 6'd0;\n            len_reg <= 6'd0;\n            loop_flag <= 1'b0;\n            valid_palindrome_reg <= 1'b0;\n            // Initialize array\n            for (integer idx = 0; idx < 50; idx = idx + 1) str_reg[idx] <= 8'h00;\n        end else begin\n            case(state)\n                IDLE: begin\n                    done <= 1'b0;\n                    best_len_reg <= 6'd1;  // Default length is 1\n                    if (start) begin\n                        len_reg <= length;\n                        i_reg <= 6'd0;\n                        state <= LOAD;\n                    end\n                end\n\n                LOAD: begin\n                    // Load all characters one by one\n                    if (i_reg < 6'd50) begin\n                        case(i_reg)\n                            6'd0: str_reg[0] <= char_0;\n                            6'd1: str_reg[1] <= char_1;\n                            6'd2: str_reg[2] <= char_2;\n                            6'd3: str_reg[3] <= char_3;\n                            6'd4: str_reg[4] <= char_4;\n                            6'd5: str_reg[5] <= char_5;\n                            6'd6: str_reg[6] <= char_6;\n                            6'd7: str_reg[7] <= char_7;\n                            6'd8: str_reg[8] <= char_8;\n                            6'd9: str_reg[9] <= char_9;\n                            6'd10: str_reg[10] <= char_10;\n                            6'd11: str_reg[11] <= char_11;\n                            6'd12: str_reg[12] <= char_12;\n                            6'd13: str_reg[13] <= char_13;\n                            6'd14: str_reg[14] <= char_14;\n                            6'd15: str_reg[15] <= char_15;\n                            6'd16: str_reg[16] <= char_16;\n                            6'd17: str_reg[17] <= char_17;\n                            6'd18: str_reg[18] <= char_18;\n                            6'd19: str_reg[19] <= char_19;\n                            6'd20: str_reg[20] <= char_20;\n                            6'd21: str_reg[21] <= char_21;\n                            6'd22: str_reg[22] <= char_22;\n                            6'd23: str_reg[23] <= char_23;\n                            6'd24: str_reg[24] <= char_24;\n                            6'd25: str_reg[25] <= char_25;\n                            6'd26: str_reg[26] <= char_26;\n                            6'd27: str_reg[27] <= char_27;\n                            6'd28: str_reg[28] <= char_28;\n                            6'd29: str_reg[29] <= char_29;\n                            6'd30: str_reg[30] <= char_30;\n                            6'd31: str_reg[31] <= char_31;\n                            6'd32: str_reg[32] <= char_32;\n                            6'd33: str_reg[33] <= char_33;\n                            6'd34: str_reg[34] <= char_34;\n                            6'd35: str_reg[35] <= char_35;\n                            6'd36: str_reg[36] <= char_36;\n                            6'd37: str_reg[37] <= char_37;\n                            6'd38: str_reg[38] <= char_38;\n                            6'd39: str_reg[39] <= char_39;\n                            6'd40: str_reg[40] <= char_40;\n                            6'd41: str_reg[41] <= char_41;\n                            6'd42: str_reg[42] <= char_42;\n                            6'd43: str_reg[43] <= char_43;\n                            6'd44: str_reg[44] <= char_44;\n                            6'd45: str_reg[45] <= char_45;\n                            6'd46: str_reg[46] <= char_46;\n                            6'd47: str_reg[47] <= char_47;\n                            6'd48: str_reg[48] <= char_48;\n                            6'd49: str_reg[49] <= char_49;\n                        endcase\n                        i_reg <= i_reg + 6'd1;\n                    end else begin\n                        state <= SEARCH;\n                        i_reg <= 6'd0;\n                        j_reg <= 6'd0;\n                    end\n                end\n\n                SEARCH: begin\n                    // Outer loop (start index)\n                    if (i_reg < len_reg) begin\n                        if (j_reg < len_reg) begin\n                            // Inner loop (end index)\n                            curr_start <= i_reg;\n                            curr_len <= j_reg - i_reg + 6'd1;\n                            k_reg <= i_reg;\n                            valid_palindrome_reg <= 1'b1;\n                            state <= COMPARE;\n                        end else begin\n                            // Move to next start index\n                            i_reg <= i_reg + 6'd1;\n                            j_reg <= i_reg;\n                        end\n                    end else begin\n                        // Search complete\n                        state <= UPDATE;\n                    end\n                end\n\n                COMPARE: begin\n                    if (k_reg < (curr_start + (curr_len >> 1))) begin\n                        if (is_valid_char(str_reg[k_reg]) && \n                            is_valid_char(str_reg[curr_start + curr_len - 6'd1 - (k_reg - curr_start)]) && \n                            str_reg[k_reg] == str_reg[curr_start + curr_len - 6'd1 - (k_reg - curr_start)]) begin\n                            k_reg <= k_reg + 6'd1;\n                        end else begin\n                            valid_palindrome_reg <= 1'b0;\n                        end\n                    end else begin\n                        if (valid_palindrome_reg) begin\n                            // Update best palindrome\n                            if (curr_len > best_len_reg) begin\n                                best_len_reg <= curr_len;\n                                best_start_reg <= curr_start;\n                            end\n                        end\n                        // Proceed to next end index\n                        j_reg <= j_reg + 6'd1;\n                        state <= SEARCH;\n                    end\n                end\n\n                UPDATE: begin\n                    result_start <= best_start_reg;\n                    result_len <= best_len_reg;\n                    state <= FINISH;\n                    done <= 1'b1;\n                end\n\n                FINISH: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule